 plan=load(PLAN);targets=load(TARGETS);static=load(STATIC);docs={k:trace(v) for k,v in TRACES.items()};assert plan['status']=='committed-before-capture-final-r7-plan';assert static['status']=='confirmed-current-final-r7-static-portable-profile';assert static['unknown_fields']==[] and static['blocking_findings']==[]
