  assert d['status']=='confirmed-current-final-r7-observation-only',(name,d['status']);assert d['summary']['completion_requirements_met'] is True;assert d['capture']['error'] is None and d['capture']['hook_failures']==[];assert all(v is False for v in d['privacy'].values());assert d['summary']['event_count']==len(d['events'])>0
