 auth={k:True for k in ['skill_root','flick_top_animation','non_normal_after_icon','multiple_add_after_side_visual','advanced_mesh','threshold_shader_mapping','all_family_pool_reuse','field_setup','field_pause_gameover','combo_ap_complete','score_digits_complete','add_score_coroutine','judge_timing','score_up_type_5','life_warning','guard','never_die','life_later_wins','judge_skill','fever_gameover_order','ordinary_production_chart']};auth['habahiro_exact']=False;auth['habahiro_degraded']=True
 out={'schema_version':1,'status':'confirmed-current-final-r7-completion-profile','sample':targets['sample'],'source':{'plan_sha256':sha(PLAN),'targets_sha256':sha(TARGETS),'static_profile_sha256':sha(STATIC),'traces':{k:{'path':str(v.relative_to(H)).replace('\\','/'),'sha256':sha(v),'event_count':docs[k]['summary']['event_count'],'relative_frame_count':docs[k]['summary']['relative_frame_count']} for k,v in TRACES.items()}},'coverage':{'event_count':sum(x['summary']['event_count'] for x in docs.values()),'aggregate_relative_frame_count':sum(x['summary']['relative_frame_count'] for x in docs.values()),'observed_owner_target_count':len(owner),'observed_setter_target_count':len(setter),'owner_event_counts':dict(sorted(owner.items())),'owner_enter_counts':dict(sorted(enters.items())),'owner_setter_counts':{f'{a}/{b}':n for (a,b),n in sorted(pairs.items())}},'scenario_dispositions':scenarios,'remaining_pr_cases':pr,'authorization':auth,'portable_static':{'advanced_mesh':static['advanced_mesh'],'shader':static['shader']['portable_semantic'],'hud':{'score':static['hud']['score'],'add_score':static['hud']['add_score'],'result_judge':static['hud']['result_judge'],'score_up_type_5':static['hud']['score_up_type_5'],'life':static['hud']['life'],'life_skill':static['hud']['life_skill']}},'limits':['Exact HABAHIRO remains open-not-claimed and is not changed by R7.','Guard/NeverDie/Judge/Crescendo routes are authorized from exact current method, scene, atlas and clip evidence; no synthetic runtime event was injected.','Unity GPU binary parity remains excluded; threshold uses the current decoded shader semantic as an explicit Pixi portable equivalent.'],'unknown_fields':[],'blocking_findings':[]}
